head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.onloadcompleted = function() {};
scwin.btn_wframeModal_onclick = function(e) {
    var url = "./windowContainer_modal_WESD-512_(WSQ-4621)_wframePopup.xml"
    var data = {
        paramsData1: dma_params.getJSON(),
        paramsData2: "샘플파라미터",
        callbackFn: "scwin.popupCallBack"
    };
    var options = {
        id: "wframePop", // 팝업 id 에 '_'를 제외한 특수기호 사용 금지
        popupName: "직원 조회", // 팝업 타이틀
        width: 560,
        height: 500,
        modal: true,
        top: "167px",
        left: "187px",
        frameModal: scwin.$w.getFrameId()
    };
    scwin.openPopup(scwin, url, options, data);
};
scwin.openPopup = function(scwin, url, opt, data) {
    try {
        var _dataObj = {
            type: "json",
            data: data,
            name: "param"
        };
        var options = {
            id: opt.id,
            type: opt.type || "wframePopup",
            width: opt.width,
            height: opt.height,
            top: opt.top,
            left: opt.left,
            popupName: opt.popupName || "",
            modal: (opt.modal == false) ? false : true,
            useModalStack: (opt.useModalStack == false) ? false : true,
            style: opt.style || "",
            srcData: opt.srcData || null,
            destData: opt.destData || null,
            dataObject: _dataObj,
            xml: opt.xml || null,
            resizable: (opt.resizable == false) ? false : true,
            status: opt.status || false,
            menubar: opt.menubar || false,
            scrollbars: true,
            title: opt.title || false,
            useMaximize: opt.useMaximize || false,
            useModalDisable: opt.useModalDisable || false,
            closeAction: opt.closeAction || "",
            className: opt.className || "",
            fullscreen: opt.fullscreen || false,
            useControl: opt.useControl || false,
            foldOnMinimized: opt.foldOnMinimized || false,
            controls: opt.controls || {
                minimize: false,
                maximize: false,
                close: false
            },
            foldSize: opt.foldSize || {
                width: 500
            },
            useATagBtn: opt.useATagBtn || false,
            disableCloseButton: opt.disableCloseButton || false,
            alwaysOnTop: opt.alwaysOnTop || false,
            windowDragMove: opt.windowDragMove || false,
            processMsgFrame: opt.processMsgFrame || false,
            frameModal: opt.frameModal,
            isPopupCloseAction: opt.isPopupCloseAction || false
        };
        if (options.type == "browserPopup") {
            if (options.closeAction) {
                _dataObj.data._menuInfo['closeAction'] = options.closeAction;
            }
            options.closeAction = ""
        } else {
            if (options.isPopupCloseAction) {
                options.popupCloseAction = options.closeAction;
                options.closeAction = "";
            }
        }
        options.dataObject = _dataObj;
        return scwin.$w.openPopup(url, options);
    } catch (e) {
        console.error("[com.cf.win._openPopup] Exception :: " + e);
    }
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /**
     * 함수설명 : 버튼 클릭 이벤트 - wframe 팝업 (Modeless, frameModal:기본값)
     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
